package com.smeal.controller; import com.smeal.dto.*;import com.smeal.service.MLIntegrationService;import jakarta.validation.Valid;import java.util.Map;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/recommendations") public class RecommendationController {private final MLIntegrationService ml;public RecommendationController(MLIntegrationService m){ml=m;}@PostMapping("/suggest")public Map<String,Object> suggest(@Valid @RequestBody MealRequestDTO r){int max=r.maxSuggestions()==null?10:r.maxSuggestions();return Map.of("suggestions",ml.recommend(r.selectedFoods()).stream().limit(max).map(x->Map.of("food",x.food(),"reason",x.reason(),"scoreBoost",x.score())).toList());}}
